CREATE INDEX IF NOT EXISTS community_feed_posts_space_idx ON public.community_feed_posts (space_id, created_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS community_feed_posts_author_idx ON public.community_feed_posts (author_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_feed_posts_popular_idx ON public.community_feed_posts (community_id, reaction_count DESC, created_at DESC) WHERE status = 'published';
CREATE TABLE IF NOT EXISTS public.community_feed_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_feed_posts(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, parent_id uuid REFERENCES public.community_feed_comments(id) ON DELETE SET NULL, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'published', reaction_count integer NOT NULL DEFAULT 0, removed_by uuid, removed_reason text, edited_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT community_feed_comments_status_check CHECK (status IN ('published', 'removed', 'deleted')), CONSTRAINT community_feed_comments_body_len CHECK (char_length(body) <= 5000));
