CREATE TABLE IF NOT EXISTS public.community_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, token_hash text NOT NULL, email text, tier_id uuid REFERENCES public.community_tiers(id) ON DELETE SET NULL, max_uses integer, uses integer NOT NULL DEFAULT 0, expires_at timestamptz, revoked_at timestamptz, created_by uuid, complimentary boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_invites_token_key UNIQUE (token_hash), CONSTRAINT community_invites_token_shape CHECK (token_hash ~ '^[0-9a-f]{64}$'), CONSTRAINT community_invites_email_lower CHECK (email IS NULL OR email = lower(email)), CONSTRAINT community_invites_uses_check CHECK (uses >= 0 AND (max_uses IS NULL OR max_uses >= 1)));
