CREATE TABLE IF NOT EXISTS public.community_event_rsvps (event_id uuid NOT NULL REFERENCES public.community_events(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'going', attended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (event_id, user_id), CONSTRAINT community_event_rsvps_status_check CHECK (status IN ('going', 'waitlist', 'cancelled')));
CREATE INDEX IF NOT EXISTS community_event_rsvps_queue_idx ON public.community_event_rsvps (event_id, status, updated_at);
