CREATE TABLE IF NOT EXISTS public.community_levels (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, level integer NOT NULL, name text NOT NULL, min_points integer NOT NULL DEFAULT 0, unlocks text, PRIMARY KEY (community_id, level), CONSTRAINT community_levels_level_check CHECK (level BETWEEN 1 AND 20), CONSTRAINT community_levels_name_len CHECK (char_length(name) BETWEEN 1 AND 40), CONSTRAINT community_levels_points_check CHECK (min_points >= 0));
CREATE TABLE IF NOT EXISTS public.community_point_events (id bigserial PRIMARY KEY, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, points integer NOT NULL, reason text NOT NULL, source_key text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_point_events_once UNIQUE (community_id, user_id, source_key), CONSTRAINT community_point_events_reason_check CHECK (reason IN ('reaction_received', 'course_completed', 'event_attended', 'admin_award', 'admin_adjust')), CONSTRAINT community_point_events_points_check CHECK (points BETWEEN -100000 AND 100000), CONSTRAINT community_point_events_key_len CHECK (char_length(source_key) BETWEEN 1 AND 200));
CREATE INDEX IF NOT EXISTS community_point_events_recent_idx ON public.community_point_events (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_badges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, description text, icon text, kind text NOT NULL DEFAULT 'manual', rule jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_badges_name_len CHECK (char_length(name) BETWEEN 1 AND 60), CONSTRAINT community_badges_description_len CHECK (description IS NULL OR char_length(description) <= 300), CONSTRAINT community_badges_kind_check CHECK (kind IN ('manual', 'milestone', 'course', 'event', 'achievement')));
CREATE INDEX IF NOT EXISTS community_badges_community_idx ON public.community_badges (community_id);
CREATE TABLE IF NOT EXISTS public.community_member_badges (badge_id uuid NOT NULL REFERENCES public.community_badges(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, awarded_by uuid, awarded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (badge_id, user_id));
CREATE INDEX IF NOT EXISTS community_member_badges_member_idx ON public.community_member_badges (community_id, user_id);
CREATE TABLE IF NOT EXISTS public.community_activity (id bigserial PRIMARY KEY, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid, kind text NOT NULL, target_type text, target_id text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_activity_kind_check CHECK (kind IN ('joined', 'post', 'comment', 'reaction', 'lesson_completed', 'course_completed', 'rsvp', 'attended', 'level_up', 'left')));
CREATE INDEX IF NOT EXISTS community_activity_community_idx ON public.community_activity (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_activity_user_idx ON public.community_activity (user_id, created_at);
CREATE TABLE IF NOT EXISTS public.community_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, kind text NOT NULL, actor_id uuid, target_type text, target_id text, title text NOT NULL, body text, url text, read_at timestamptz, dedupe_key text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_notifications_dedupe_key UNIQUE (dedupe_key), CONSTRAINT community_notifications_kind_check CHECK (kind IN ('reaction', 'comment', 'reply', 'mention', 'announcement', 'event', 'event_reminder', 'course_unlocked', 'level_up', 'membership', 'admin_message', 'report', 'join_request')), CONSTRAINT community_notifications_title_len CHECK (char_length(title) BETWEEN 1 AND 200), CONSTRAINT community_notifications_body_len CHECK (body IS NULL OR char_length(body) <= 500));
CREATE INDEX IF NOT EXISTS community_notifications_user_idx ON public.community_notifications (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_notifications_unread_idx ON public.community_notifications (user_id) WHERE read_at IS NULL;
CREATE TABLE IF NOT EXISTS public.community_jobs (id bigserial PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, run_at timestamptz NOT NULL DEFAULT now(), state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, lease_until timestamptz, idempotency_key text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, CONSTRAINT community_jobs_idempotency_key UNIQUE (idempotency_key), CONSTRAINT community_jobs_kind_check CHECK (kind IN ('fanout_announcement', 'fanout_event', 'event_reminder', 'recount', 'rollup', 'trending', 'video_poll')), CONSTRAINT community_jobs_state_check CHECK (state IN ('pending', 'running', 'done', 'failed')));
CREATE INDEX IF NOT EXISTS community_jobs_due_idx ON public.community_jobs (run_at, id) WHERE state = 'pending';
CREATE INDEX IF NOT EXISTS community_jobs_lease_idx ON public.community_jobs (lease_until) WHERE state = 'running';
CREATE TABLE IF NOT EXISTS public.community_daily_stats (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, day date NOT NULL, members integer NOT NULL DEFAULT 0, new_members integer NOT NULL DEFAULT 0, left_members integer NOT NULL DEFAULT 0, active_members integer NOT NULL DEFAULT 0, posts integer NOT NULL DEFAULT 0, comments integer NOT NULL DEFAULT 0, reactions integer NOT NULL DEFAULT 0, rsvps integer NOT NULL DEFAULT 0, lessons_completed integer NOT NULL DEFAULT 0, PRIMARY KEY (community_id, day));
CREATE TABLE IF NOT EXISTS public.media_videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, community_id uuid REFERENCES public.communities(id) ON DELETE SET NULL, provider text NOT NULL DEFAULT 'storage', status text NOT NULL DEFAULT 'uploading', storage_path text, provider_asset_id text, playback_id text, thumbnail_url text, duration_seconds integer, width integer, height integer, size_bytes bigint, mime text, captions_path text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT media_videos_provider_asset_once UNIQUE (provider, provider_asset_id), CONSTRAINT media_videos_provider_check CHECK (provider IN ('storage', 'mux', 'cloudflare', 'bunny')), CONSTRAINT media_videos_status_check CHECK (status IN ('uploading', 'processing', 'ready', 'failed')));
CREATE INDEX IF NOT EXISTS media_videos_creator_idx ON public.media_videos (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS media_videos_community_idx ON public.media_videos (community_id) WHERE community_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.media_video_events (provider text NOT NULL, event_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (provider, event_id));
CREATE OR REPLACE FUNCTION public.community_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN NEW.updated_at := now(); RETURN NEW; END $f$;
CREATE OR REPLACE FUNCTION public.community_member_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.community_id = NEW.community_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'active' THEN UPDATE public.communities SET member_count = greatest(member_count - 1, 0) WHERE id = OLD.community_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'active' THEN UPDATE public.communities SET member_count = member_count + 1 WHERE id = NEW.community_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_post_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.community_id = NEW.community_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'published' THEN UPDATE public.communities SET post_count = greatest(post_count - 1, 0) WHERE id = OLD.community_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'published' THEN UPDATE public.communities SET post_count = post_count + 1 WHERE id = NEW.community_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_comment_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.post_id = NEW.post_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'published' THEN UPDATE public.community_feed_posts SET comment_count = greatest(comment_count - 1, 0) WHERE id = OLD.post_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'published' THEN UPDATE public.community_feed_posts SET comment_count = comment_count + 1, last_activity_at = greatest(last_activity_at, NEW.created_at) WHERE id = NEW.post_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_reaction_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_type text; v_id uuid; v_step integer; BEGIN IF TG_OP = 'INSERT' THEN v_type := NEW.target_type; v_id := NEW.target_id; v_step := 1; ELSE v_type := OLD.target_type; v_id := OLD.target_id; v_step := -1; END IF; IF v_type = 'post' THEN UPDATE public.community_feed_posts SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; ELSIF v_type = 'comment' THEN UPDATE public.community_feed_comments SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; ELSIF v_type = 'message' THEN UPDATE public.community_messages SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_going_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.event_id = NEW.event_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'going' THEN UPDATE public.community_events SET going_count = greatest(going_count - 1, 0) WHERE id = OLD.event_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'going' THEN UPDATE public.community_events SET going_count = going_count + 1 WHERE id = NEW.event_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_vote_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE public.community_poll_options SET vote_count = vote_count + 1 WHERE id = NEW.option_id; ELSE UPDATE public.community_poll_options SET vote_count = greatest(vote_count - 1, 0) WHERE id = OLD.option_id; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_points_apply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_community uuid; v_user uuid; v_step integer; BEGIN IF TG_OP = 'INSERT' THEN v_community := NEW.community_id; v_user := NEW.user_id; v_step := NEW.points; ELSE v_community := OLD.community_id; v_user := OLD.user_id; v_step := -OLD.points; END IF; UPDATE public.community_members m SET points = m.points + v_step, level = coalesce((SELECT max(l.level) FROM public.community_levels l WHERE l.community_id = m.community_id AND l.min_points <= m.points + v_step), 1) WHERE m.community_id = v_community AND m.user_id = v_user; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_audit_append_only() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.community_id IS NOT NULL AND NEW.community_id IS NULL AND (to_jsonb(NEW) - 'community_id') = (to_jsonb(OLD) - 'community_id') THEN RETURN NEW; END IF; END IF; RAISE EXCEPTION 'community_audit_log is append only: % is refused', lower(TG_OP) USING ERRCODE = '42501'; END $f$;
CREATE OR REPLACE FUNCTION public.community_cast_vote(p_poll uuid, p_user uuid, p_options uuid[]) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_poll public.community_polls%ROWTYPE; v_options uuid[]; v_valid integer; BEGIN SELECT * INTO v_poll FROM public.community_polls WHERE id = p_poll; IF NOT FOUND THEN RETURN 'not_found'; END IF; IF v_poll.closes_at IS NOT NULL AND v_poll.closes_at <= now() THEN RETURN 'closed'; END IF; v_options := ARRAY(SELECT DISTINCT o FROM unnest(coalesce(p_options, '{}'::uuid[])) AS o WHERE o IS NOT NULL); IF cardinality(v_options) > 1 AND NOT v_poll.multiple THEN RETURN 'too_many'; END IF; SELECT count(*) INTO v_valid FROM public.community_poll_options WHERE poll_id = p_poll AND id = ANY (v_options); IF v_valid <> cardinality(v_options) THEN RETURN 'bad_option'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('community_vote:' || p_poll::text || ':' || p_user::text, 0)); DELETE FROM public.community_poll_votes WHERE poll_id = p_poll AND user_id = p_user AND NOT (option_id = ANY (v_options)); INSERT INTO public.community_poll_votes (poll_id, option_id, user_id) SELECT p_poll, o, p_user FROM unnest(v_options) AS o ON CONFLICT (option_id, user_id) DO NOTHING; RETURN 'ok'; END $f$;
CREATE OR REPLACE FUNCTION public.community_rsvp(p_event uuid, p_user uuid, p_going boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_event public.community_events%ROWTYPE; v_current text; v_status text; v_going integer; BEGIN SELECT * INTO v_event FROM public.community_events WHERE id = p_event FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'community_rsvp: no event %', p_event USING ERRCODE = 'P0002'; END IF; SELECT status INTO v_current FROM public.community_event_rsvps WHERE event_id = p_event AND user_id = p_user; IF NOT p_going THEN IF v_current IS NULL OR v_current = 'cancelled' THEN RETURN 'cancelled'; END IF; UPDATE public.community_event_rsvps SET status = 'cancelled' WHERE event_id = p_event AND user_id = p_user; IF v_current = 'going' AND v_event.capacity IS NOT NULL AND v_event.status = 'scheduled' THEN UPDATE public.community_event_rsvps r SET status = 'going' FROM (SELECT user_id FROM public.community_event_rsvps WHERE event_id = p_event AND status = 'waitlist' ORDER BY updated_at, user_id LIMIT 1) w WHERE r.event_id = p_event AND r.user_id = w.user_id; END IF; RETURN 'cancelled'; END IF; IF v_event.status <> 'scheduled' THEN RETURN coalesce(nullif(v_current, 'cancelled'), 'cancelled'); END IF; IF v_current IN ('going', 'waitlist') THEN RETURN v_current; END IF; SELECT count(*) INTO v_going FROM public.community_event_rsvps WHERE event_id = p_event AND status = 'going'; v_status := CASE WHEN v_event.capacity IS NULL OR v_going < v_event.capacity THEN 'going' ELSE 'waitlist' END; INSERT INTO public.community_event_rsvps (event_id, user_id, community_id, status) VALUES (p_event, p_user, v_event.community_id, v_status) ON CONFLICT (event_id, user_id) DO UPDATE SET status = EXCLUDED.status; RETURN v_status; END $f$;
CREATE OR REPLACE FUNCTION public.community_redeem_invite(p_token_hash text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_invite public.community_invites%ROWTYPE; v_email text; v_used boolean; v_new boolean := false; BEGIN SELECT * INTO v_invite FROM public.community_invites WHERE token_hash = p_token_hash FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_invite.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'revoked', 'community_id', v_invite.community_id); END IF; IF v_invite.expires_at IS NOT NULL AND v_invite.expires_at <= now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'expired', 'community_id', v_invite.community_id); END IF; IF v_invite.email IS NOT NULL THEN SELECT lower(u.email::text) INTO v_email FROM auth.users u WHERE u.id = p_user AND u.email_confirmed_at IS NOT NULL; IF v_email IS NULL OR v_email <> lower(v_invite.email) THEN RETURN jsonb_build_object('ok', false, 'reason', 'email_mismatch', 'community_id', v_invite.community_id); END IF; END IF; v_used := EXISTS (SELECT 1 FROM public.community_invite_uses WHERE invite_id = v_invite.id AND user_id = p_user); IF NOT v_used AND v_invite.max_uses IS NOT NULL AND v_invite.uses >= v_invite.max_uses THEN RETURN jsonb_build_object('ok', false, 'reason', 'used_up', 'community_id', v_invite.community_id); END IF; IF NOT v_used THEN INSERT INTO public.community_invite_uses (invite_id, user_id) VALUES (v_invite.id, p_user) ON CONFLICT (invite_id, user_id) DO NOTHING; v_new := FOUND; IF v_new THEN UPDATE public.community_invites SET uses = uses + 1 WHERE id = v_invite.id; END IF; END IF; RETURN jsonb_build_object('ok', true, 'community_id', v_invite.community_id, 'tier_id', v_invite.tier_id, 'complimentary', v_invite.complimentary, 'invite_id', v_invite.id, 'new', v_new); END $f$;
CREATE OR REPLACE FUNCTION public.community_award_points(p_community uuid, p_user uuid, p_points integer, p_reason text, p_source_key text, p_actor uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN INSERT INTO public.community_point_events (community_id, user_id, points, reason, source_key, actor_id) VALUES (p_community, p_user, p_points, p_reason, p_source_key, p_actor) ON CONFLICT (community_id, user_id, source_key) DO NOTHING; RETURN FOUND; END $f$;
CREATE OR REPLACE FUNCTION public.community_claim_jobs(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.community_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN UPDATE public.community_jobs SET state = 'failed', finished_at = now(), lease_until = NULL, last_error = coalesce(last_error, 'its lease ran out 5 times') WHERE state = 'running' AND lease_until < now() AND attempts >= 5; RETURN QUERY WITH picked AS (SELECT j.id FROM public.community_jobs j WHERE (j.state = 'pending' AND j.run_at <= now()) OR (j.state = 'running' AND j.lease_until < now()) ORDER BY j.run_at, j.id LIMIT greatest(coalesce(p_limit, 0), 0) FOR UPDATE SKIP LOCKED) UPDATE public.community_jobs j SET state = 'running', lease_until = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 60), 1)), attempts = j.attempts + 1 FROM picked WHERE j.id = picked.id RETURNING j.*; END $f$;
CREATE OR REPLACE FUNCTION public.community_leaderboard(p_community uuid, p_since timestamptz, p_limit integer) RETURNS TABLE (user_id uuid, points bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT e.user_id, sum(e.points)::bigint AS points FROM public.community_point_events e JOIN public.community_members m ON m.community_id = e.community_id AND m.user_id = e.user_id AND m.status = 'active' WHERE e.community_id = p_community AND e.created_at >= p_since GROUP BY e.user_id HAVING sum(e.points) > 0 ORDER BY 2 DESC, 1 LIMIT greatest(least(coalesce(p_limit, 20), 100), 0) $f$;
CREATE OR REPLACE FUNCTION public.community_role_of(p_community uuid, p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT m.role FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = p_user AND m.status = 'active' AND m.banned_at IS NULL $f$;
CREATE OR REPLACE FUNCTION public.community_can_read_space(p_space uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_uid uuid := auth.uid(); v_space record; v_member record; v_rule jsonb; v_tiers text[]; v_products text[]; v_roles text[]; v_min integer; BEGIN IF v_uid IS NULL OR p_space IS NULL THEN RETURN false; END IF; SELECT s.community_id, s.view_access, s.archived_at, c.status AS community_status, c.deleted_at, c.suspended_at INTO v_space FROM public.community_spaces s JOIN public.communities c ON c.id = s.community_id WHERE s.id = p_space; IF NOT FOUND OR v_space.archived_at IS NOT NULL OR v_space.deleted_at IS NOT NULL OR v_space.suspended_at IS NOT NULL OR v_space.community_status = 'suspended' THEN RETURN false; END IF; SELECT m.role, m.status, m.tier_id, m.level, m.banned_at INTO v_member FROM public.community_members m WHERE m.community_id = v_space.community_id AND m.user_id = v_uid; IF NOT FOUND OR v_member.status <> 'active' OR v_member.banned_at IS NOT NULL THEN RETURN false; END IF; IF v_member.role IN ('owner', 'admin', 'moderator') THEN RETURN true; END IF; v_rule := CASE WHEN jsonb_typeof(v_space.view_access) = 'object' THEN v_space.view_access ELSE '{}'::jsonb END; v_tiers := CASE WHEN jsonb_typeof(v_rule -> 'tierIds') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'tierIds')) ELSE '{}'::text[] END; v_products := CASE WHEN jsonb_typeof(v_rule -> 'productIds') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'productIds')) ELSE '{}'::text[] END; v_roles := CASE WHEN jsonb_typeof(v_rule -> 'roles') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'roles')) ELSE '{}'::text[] END; v_min := CASE WHEN jsonb_typeof(v_rule -> 'minLevel') = 'number' THEN floor((v_rule ->> 'minLevel')::numeric)::integer ELSE NULL END; IF v_min IS NOT NULL AND coalesce(v_member.level, 1) < v_min THEN RETURN false; END IF; IF cardinality(v_tiers) = 0 AND cardinality(v_products) = 0 AND cardinality(v_roles) = 0 THEN RETURN true; END IF; IF v_member.tier_id IS NOT NULL AND v_member.tier_id::text = ANY (v_tiers) THEN RETURN true; END IF; IF v_member.role = ANY (v_roles) THEN RETURN true; END IF; IF cardinality(v_products) > 0 THEN IF to_regclass('public.entitlements') IS NOT NULL AND EXISTS (SELECT 1 FROM public.entitlements e WHERE e.buyer_id = v_uid AND e.product_id::text = ANY (v_products)) THEN RETURN true; END IF; IF to_regclass('public.memberships') IS NOT NULL AND EXISTS (SELECT 1 FROM public.memberships ms WHERE ms.buyer_id = v_uid AND ms.product_id::text = ANY (v_products) AND public.membership_grants_access(ms.status, ms.current_period_end, ms.past_due_since, now())) THEN RETURN true; END IF; END IF; RETURN false; END $f$;
CREATE OR REPLACE TRIGGER platform_flags_touch_updated_at BEFORE UPDATE ON public.platform_flags FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER communities_touch_updated_at BEFORE UPDATE ON public.communities FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_tiers_touch_updated_at BEFORE UPDATE ON public.community_tiers FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_members_touch_updated_at BEFORE UPDATE ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_spaces_touch_updated_at BEFORE UPDATE ON public.community_spaces FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_feed_posts_touch_updated_at BEFORE UPDATE ON public.community_feed_posts FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_feed_comments_touch_updated_at BEFORE UPDATE ON public.community_feed_comments FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_events_touch_updated_at BEFORE UPDATE ON public.community_events FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_event_rsvps_touch_updated_at BEFORE UPDATE ON public.community_event_rsvps FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER media_videos_touch_updated_at BEFORE UPDATE ON public.media_videos FOR EACH ROW EXECUTE FUNCTION public.community_touch_updated_at();
CREATE OR REPLACE TRIGGER community_members_count AFTER INSERT OR DELETE OR UPDATE OF status, community_id ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.community_member_count();
CREATE OR REPLACE TRIGGER community_feed_posts_count AFTER INSERT OR DELETE OR UPDATE OF status, community_id ON public.community_feed_posts FOR EACH ROW EXECUTE FUNCTION public.community_post_count();
CREATE OR REPLACE TRIGGER community_feed_comments_count AFTER INSERT OR DELETE OR UPDATE OF status, post_id ON public.community_feed_comments FOR EACH ROW EXECUTE FUNCTION public.community_comment_count();
CREATE OR REPLACE TRIGGER community_reactions_count AFTER INSERT OR DELETE ON public.community_reactions FOR EACH ROW EXECUTE FUNCTION public.community_reaction_count();
CREATE OR REPLACE TRIGGER community_event_rsvps_count AFTER INSERT OR DELETE OR UPDATE OF status, event_id ON public.community_event_rsvps FOR EACH ROW EXECUTE FUNCTION public.community_going_count();
CREATE OR REPLACE TRIGGER community_poll_votes_count AFTER INSERT OR DELETE ON public.community_poll_votes FOR EACH ROW EXECUTE FUNCTION public.community_vote_count();
CREATE OR REPLACE TRIGGER community_point_events_apply AFTER INSERT OR DELETE ON public.community_point_events FOR EACH ROW EXECUTE FUNCTION public.community_points_apply();
CREATE OR REPLACE TRIGGER community_audit_log_append_only BEFORE UPDATE OR DELETE ON public.community_audit_log FOR EACH ROW EXECUTE FUNCTION public.community_audit_append_only();
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_deleted_row()') IS NULL THEN RAISE NOTICE 'communities: part 66 has not run, deleted community rows are not kept.'; RETURN; END IF; DROP TRIGGER IF EXISTS communities_keep_deleted ON public.communities; CREATE TRIGGER communities_keep_deleted AFTER DELETE ON public.communities FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_tiers_keep_deleted ON public.community_tiers; CREATE TRIGGER community_tiers_keep_deleted AFTER DELETE ON public.community_tiers FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_members_keep_deleted ON public.community_members; CREATE TRIGGER community_members_keep_deleted AFTER DELETE ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_feed_posts_keep_deleted ON public.community_feed_posts; CREATE TRIGGER community_feed_posts_keep_deleted AFTER DELETE ON public.community_feed_posts FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); DROP TRIGGER IF EXISTS community_events_keep_deleted ON public.community_events; CREATE TRIGGER community_events_keep_deleted AFTER DELETE ON public.community_events FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_deleted_row(); END $do$;
